def search(self, query):
    """Books whose titles share words with `query`, the most shared
    first, then by title; `subject:WORD` terms keep only the books with
    one of those subjects."""
    subjects = {fold(t[len("subject:"):]) for t in query.split() if t.startswith("subject:")}
    want = set(words(" ".join(t for t in query.split() if not t.startswith("subject:"))))
    books = [b for b in self.books.values() if not subjects or subjects & {fold(s) for s in b.subjects}]
    if not want:
        return sorted(books, key=lambda b: b.title) if subjects else []
